from math import isqrt

def isp(n):
 if n<2:return False
 return all(n%d for d in range(2,isqrt(n)+1))
# compare simple operations predicates
for form in ['sum','prod','sumprod','diff','a2b2','abplus']:
 for p in range(-4,5):
  for q in range(-4,5):
   for r in range(-4,5):
    vals=[]
    for a in range(1,6):
     for b in range(1,8):
      n={'sum':a+b+p,'prod':a*b+p,'sumprod':a*b+p*a+q*b+r,'diff':abs(a-b)+p,'a2b2':a*a+b*b+p,'abplus':(a+b)*(a*b)+p}[form]
      vals.append(n)
    # prime, composite, odd, even; expression constants irrelevant for last
    for typ in ['prime','nprime','odd','even','sq','nonsq']:
     pred=[]; ix=0
     for a in range(1,6):
      row=[]
      for b in range(1,8):
       n=vals[ix];ix+=1
       x=isp(n) if typ=='prime' else (n>=2 and not isp(n)) if typ=='nprime' else n%2==1 if typ=='odd' else n%2==0 if typ=='even' else (n>=0 and isqrt(n)**2==n) if typ=='sq' else (n>=0 and isqrt(n)**2!=n)
       row.append(int(x))
      pred.append(row)
     score=sum(x==y for rr,ss in zip(obs,pred) for x,y in zip(rr,ss))
     if score>=28: print(score,form,p,q,r,typ)

